export function chapter(year) {
  if(year<1900) return '第一卷 · 状元转身';
  if(year<1906) return '第二卷 · 实业与新学';
  if(year<1916) return '第三卷 · 制度的岔路';
  if(year<1922) return '第四卷 · 繁荣的两面';
  return '第五卷 · 潮落与传承';
}
